 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator rows/columns are the full lines of color 8.
    sep_rows = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    nr, nc = len(row_bounds) - 1, len(col_bounds) - 1
    cells = [[0 for _ in range(nc)] for _ in range(nr)]
    active_rows, active_cols = {}, {}
    for i in range(nr):
        for j in range(nc):
            for r in range(row_bounds[i] + 1, row_bounds[i + 1]):
                for c in range(col_bounds[j] + 1, col_bounds[j + 1]):
                    v = grid[r][c]
                    if v not in (0, 8):
                        cells[i][j] = v
                        active_rows[i] = v
                        active_cols[j] = v
    out = [row[:] for row in grid]
    for i in range(nr):
        for j in range(nc):
            colors = set()
            if i in active_rows:
                colors.add(active_rows[i])
            if j in active_cols:
                colors.add(active_cols[j])
            if len(colors) == 1:
                color = next(iter(colors))
            elif colors == {2, 3}:
                color = 6
            else:
                color = cells[i][j]
            for r in range(row_bounds[i] + 1, row_bounds[i + 1]):
                for c in range(col_bounds[j] + 1, col_bounds[j + 1]):
                    out[r][c] = color
    return out
